        print(f"Parameter {name}: {param.annotation} (type: {type(param.annotation)})")

    try:
        hints = get_type_hints(read_item)
        print(f"Type hints: {hints}")
    except Exception as e:
        print(f"get_type_hints failed: {e}")

if __name__ == "__main__":
    test_annotations()

