from __future__ import annotations
import inspect
from typing import Any, Callable
from fastapi.dependencies.utils import get_typed_signature

class Item:
    def __init__(self, name: str):
        self.name = name

def test_func(item_id: int, item: Item):
    return {"item_id": item_id, "item": item}

def test_get_typed_signature():
    sig = get_typed_signature(test_func)
    print(f"Signature: {sig}")

    for name, param in sig.parameters.items():
        print(f"Parameter {name}: {param.annotation} (type: {type(param.annotation)})")

    # Assertions
    assert sig.parameters["item_id"].annotation is int
    assert sig.parameters["item"].annotation is Item
    print("All assertions passed!")

if __name__ == "__main__":
    test_get_typed_signature()

